 ('<span class="label">${t("q")} <span class="mono">${q.i+1}/${q.ids.length}</span></span></div><p class="qtext" style="margin:0">${esc(o.q[l])}</p>${parts}', '<span class="label">${t("q")} <span class="mono">${q.i+1}/${q.ids.length}</span></span></div><p class="oxh">${t("oxQ").toUpperCase()} ${q.i+1} (${omax(o)} ${t("oxPts").toUpperCase()})</p><p class="oxstem">${esc(o.q[l])}</p>${oLabels(o)}${parts}'),
